// end of generated

export type InputProps<T extends HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement> = ElementProps<T, AllHTMLAttributes<T>> & {
	is?: 'input' | 'textarea' | 'select';
	htmlSize?: number;
	invisible?: boolean;
};

// The modifiers `InputBox` passes as `rcx-*` attributes, outside the public props
type InputBoxModifiers = {
	'rcx-input-box--type'?: string;
	'rcx-input-box--multiple'?: boolean;
	'rcx-input-box--placeholder-visible'?: boolean;
	'rcx-input-box--small'?: boolean;
	'rcx-input-box--undecorated'?: boolean;
};

// Set by `InputBoxWrapper`, which sizes the input it holds
export const InputBoxWrapperContext = createContext(false);

const UNDECORATED = 'rcx-input-box--undecorated';

function Input<T extends HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>({ is = 'input', ref, className, children, ...props }: InputProps<T>) {
	const {
		'rcx-input-box--type': type,
		'rcx-input-box--multiple': multiple,
		'rcx-input-box--placeholder-visible': placeholderVisible,
		'rcx-input-box--small': small,
		'rcx-input-box--undecorated': undecoratedProp,
	} = props as typeof props & InputBoxModifiers;

	// Select and AutoComplete ask for it by class name
	const undecorated = Boolean(undecoratedProp) || (typeof className === 'string' && className.split(/\s+/).includes(UNDECORATED));
	const wrapped = useContext(InputBoxWrapperContext);

	const look = undecorated ? `${wrapped ? 'wrapped' : 'plain'}${small ? '-small' : ''}` : small ? 'small' : 'decorated';
	const kind = (type === 'textarea' && 'textarea') || (type === 'select' && (multiple ? 'multiple' : 'select')) || 'text';

	return (
		<InputFrame
			render={<Box is={is} animated rcx-input-box {...props} ref={ref} />}
			className={className}
			look={look}
			kind={kind}
			placeholderVisible={Boolean(placeholderVisible)}
		>
			{children}
		</InputFrame>
	);
}

export default Input;
